class Solution:
    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:
        seen = {''.join(sorted(w)) for w in startWords}
        ans = 0
        for w in targetWords:
            s = ''.join(sorted(w))
            if any(s[:i] + s[i + 1:] in seen for i in range(len(s))):
                ans += 1
        return ans

