class Solution:
    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:
        masks = set()
        for w in startWords:
            m = 0
            for ch in w:
                m |= 1 << (ord(ch) - 97)
            masks.add(m)
        ans = 0
        for w in targetWords:
            m = 0
            for ch in w:
                m |= 1 << (ord(ch) - 97)
            for b in range(26):
                if (m >> b) & 1 and (m ^ (1 << b)) in masks:
                    ans += 1
                    break
        return ans

